def build(lang):
    i = 0 if lang == 'fr' else 1
    def conv(v):
        if isinstance(v, tuple):
            return v[i]
        if isinstance(v, dict):
            return {k: conv(x) for k, x in v.items()}
        return v
    return conv(T)

for lang in ['fr', 'en']:
    with open(os.path.join(OUT, f'{lang}.json'), 'w') as f:
        json.dump(build(lang), f, ensure_ascii=False, indent=0)
print('ok')
